 g=d['goals'][i];p=g['reviewContext']['evidenceProfile']['profile'];rows.append({'goalId':gid,'decision':decision,'evidenceProfileRecommendation':rec,'rationale':rat,'observedEvidence':obs,'actualBoundPageObservation':vis,'exactReadCoverage':{'currentBilingualTitleAndDescription':'whole','canonicalContext':'whole fields in supplied native input; current canonical raw jurisdiction/requires and extended source/own-acquisition annotations additionally read','prerequisitesAndContext':'whole current DE/EN descriptions of directly named canonical prerequisites, successors and containing chapters; no new whole-landscape review','wholePositiveProfile':{'expectationIds':[x['id'] for x in p['expectations']],'coverageExpectations':p['coverageExpectations'],'variationAxisIds':[x['id'] for x in p['variationAxes']],'applicationCaseIds':[x['id'] for x in p['applicationCaseBriefs']]},'semanticKindLedger':'current selected record read; own semantic judgment is content-based','visual':'actual bound PDF goal page '+str(i+1)+', physical page '+str(i+3)+'; asset digest independently matched'},'uncertainties':['No blocking description/science/atomicity ambiguity observed in this assigned scope.','Official full source mapping and effective learner-facing compiler projection are separate gates; raw applicability and own-acquisition annotations alone do not prove them.','Prospective P requirements and images establish no actual learner execution, mastery or human approval.'],'goalFingerprint':g['goalFingerprint'],'pageFingerprint':g['pageFingerprint']})
